#!/usr/bin/env python3
# ---------------------------------------------------------------------------
# pocket-voxel patcher: populate the POKeDEX seen/owned flags (patcher 4).
# TS-only (rebuild game.js via cargo). Pairs with the Pokedex screen patcher.
#
# Ports gen1recomp's dex-flag writes (BattleState.lua markSeen :513 + the owned
# mark :529-534) to the matching port sites:
#   * a wild mon marks SEEN when it appears        (enemyIntro, BattleState:596)
#   * a trainer's lead + each send-out mark SEEN    (trainer.ts, :718 / :3256)
#   * a caught mon marks OWNED (+seen)              (storeCaughtMon, :4451/4465)
#   * a gift/starter marks OWNED (+seen)            (give_pokemon, Commands:695)
# Evolution already marked both. Trade/link and the Oak's-lab starter preview
# are NOT ported (no trade system / that preview event isn't wired yet).
#
# Idempotent; aborts if an anchor is missing/ambiguous.
# Run from ~/pocket-voxel: python3 apply_dex_flags.py
# ---------------------------------------------------------------------------
import base64, sys, os
EDITS = [{'path': 'voxelmon/game/battle/mon.ts', 'old': 'ICAgIGlmIChtb24uaHAgPiAwKSByZXR1cm4gbW9uOwogIH0KICByZXR1cm4gbnVsbDsKfQo=', 'new': ''}, {'path': 'voxelmon/game/battle/battle.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/battle/battle.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/battle/battle.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/battle/battle.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/battle/trainer.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/battle/trainer.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/battle/trainer.ts', 'old': 'ICAgICAgfQogICAgICByZXR1cm47CiAgICB9CiAgICB0aGlzLmVuZW15SW5kZXggPSB0aGlzLmVuZW15UGFydHkuaW5kZXhPZihuZXh0KTsKICAgIHRoaXMuc2F5TmV4dChgJHt0aGlzLnRyYWluZXJOYW1lfSBzZW50IG91dFxuJHtuZXh0LnNwZWNpZXN9IWApOwogICAgdGhpcy5hY3QoKCkgPT4gdGhpcy5zd2FwRW5lbXkobmV4dCkpOwogIH0KfQo=', 'new': ''}, {'path': 'voxelmon/game/world/script.ts', 'old': '', 'new': ''}, {'path': 'voxelmon/game/world/script.ts', 'old': '', 'new': ''}]
def main():
    root=os.getcwd()
    if not os.path.isdir(os.path.join(root,"voxelmon")):
        sys.exit("! run this from the pocket-voxel repo root (no ./voxelmon here)")
    changed=skipped=0; by_file={}
    for h in EDITS: by_file.setdefault(h["path"],[]).append(h)
    for path,hs in by_file.items():
        fp=os.path.join(root,path)
        if not os.path.isfile(fp): sys.exit(f"! missing file: {path}")
        text=open(fp,encoding="utf-8").read(); orig=text
        for h in hs:
            old=base64.b64decode(h["old"]).decode(); new=base64.b64decode(h["new"]).decode()
            if new in text: skipped+=1; continue
            n=text.count(old)
            if n==0: sys.exit(f"! anchor not found in {path}\n  (not the expected tree, or already diverged)")
            if n>1: sys.exit(f"! anchor is ambiguous in {path} ({n} matches) -- aborting")
            text=text.replace(old,new,1); changed+=1
        if text!=orig: open(fp,"w",encoding="utf-8").write(text); print(f"  patched {path}")
    print(f"done: {changed} hunk(s) applied, {skipped} already present")
    if changed==0 and skipped: print("(nothing to do -- patcher already applied)")
if __name__=="__main__": main()
